<style>
    :root { --wr-ink:#172536; --wr-muted:#66758a; --wr-navy:#243e56; --wr-navy-2:#31566f; --wr-line:#dbe3ea; --wr-surface:#fff; --wr-danger:#b42318; --wr-danger-soft:#fff1ef; --wr-amber:#b54708; --wr-amber-soft:#fff7e8; --wr-success:#147a55; --wr-success-soft:#eaf7f1; --wr-radius:10px; }
    .wr-shell{color:var(--wr-ink)}
    .wr-page-head{align-items:flex-end;display:flex;flex-wrap:wrap;gap:18px;justify-content:space-between;margin-bottom:18px}
    .wr-page-head h3{font-size:clamp(1.35rem,2vw,1.8rem);font-weight:750;letter-spacing:-.025em;margin:0}
    .wr-page-head p{color:var(--wr-muted);font-size:.9rem;margin:5px 0 0}
    .wr-actions{display:flex;flex-wrap:wrap;gap:8px}.wr-actions .btn{align-items:center;border-radius:7px;display:inline-flex;font-weight:650;gap:7px;min-height:38px}.wr-actions .btn:active,.wr-filter-actions .btn:active{transform:scale(.97)}
    .wr-filter{background:var(--wr-surface);border:1px solid var(--wr-line)!important;border-radius:var(--wr-radius);box-shadow:0 4px 14px rgba(28,50,70,.06)!important;margin-bottom:16px}
    .wr-filter-head{align-items:center;border-bottom:1px solid var(--wr-line);display:flex;justify-content:space-between;padding:11px 16px}.wr-filter-title{align-items:center;display:flex;font-size:.9rem;font-weight:750;gap:8px}.wr-filter-title i{color:var(--wr-navy-2)}
    .wr-filter .card-body{padding:14px 16px 16px}.wr-filter .form-label{color:#4d5d70;font-size:.78rem;font-weight:700;margin-bottom:5px}.wr-filter .form-control,.wr-filter .form-select{border-color:#cfd9e2;border-radius:7px;font-size:.88rem;min-height:39px}.wr-filter .form-control:focus,.wr-filter .form-select:focus{border-color:#66879f;box-shadow:0 0 0 3px rgba(49,86,111,.13)}
    .wr-filter-actions{align-items:center;display:flex;gap:8px}.wr-filter-actions .btn{border-radius:7px;font-weight:650;min-height:39px}
    .wr-active-filters,.wr-quick-filters{align-items:center;display:flex;flex-wrap:wrap;gap:7px}.wr-active-filters{border-bottom:1px solid var(--wr-line);padding:10px 16px}.wr-active-filter{align-items:center;background:#eef4ff;border:1px solid #bfdbfe;border-radius:999px;color:#1e3a8a;display:inline-flex;font-size:.78rem;font-weight:700;gap:6px;padding:.28rem .58rem;text-decoration:none}.wr-active-filter:hover{background:#dbeafe;color:#1e3a8a}.wr-quick-filters{border-top:1px dashed var(--wr-line);margin-top:12px;padding-top:12px}.wr-quick-filters .btn{font-weight:650}
    .wr-freshness{align-items:center;background:#eef3f6;border:1px solid #d8e1e8;border-radius:8px;color:#43566a;display:flex;flex-wrap:wrap;font-size:.82rem;gap:8px;justify-content:space-between;margin-bottom:16px;padding:8px 12px}.wr-freshness strong{color:var(--wr-ink);font-variant-numeric:tabular-nums}.wr-live-dot{background:var(--wr-success);border-radius:50%;box-shadow:0 0 0 4px rgba(20,122,85,.1);display:inline-block;height:7px;margin-right:7px;width:7px}
    .wr-risk-grid{display:grid;gap:12px;grid-template-columns:minmax(260px,1.25fr) repeat(2,minmax(180px,.75fr));margin-bottom:12px}.wr-risk-card{background:var(--wr-surface);border:1px solid var(--wr-line);border-radius:var(--wr-radius);min-height:118px;overflow:hidden;padding:16px 18px;position:relative}.wr-risk-card--hero{background:var(--wr-navy);border-color:var(--wr-navy);color:#fff;grid-row:span 2;min-height:248px;padding:22px}.wr-risk-card--hero:after{border:30px solid rgba(255,255,255,.055);border-radius:50%;content:'';height:190px;position:absolute;right:-55px;top:-42px;width:190px}
    .wr-kpi-label{color:var(--wr-muted);font-size:.76rem;font-weight:750;letter-spacing:.035em;text-transform:uppercase}.wr-risk-card--hero .wr-kpi-label{color:#c7d5df}.wr-kpi-value{font-size:clamp(1.45rem,2.1vw,2rem);font-variant-numeric:tabular-nums;font-weight:780;letter-spacing:-.035em;line-height:1.12;margin-top:9px}.wr-risk-card--hero .wr-kpi-value{font-size:clamp(2rem,3.4vw,3.15rem);margin-top:18px;max-width:85%}.wr-kpi-unit{font-size:.72em;font-weight:650;opacity:.78}.wr-kpi-note{color:var(--wr-muted);font-size:.78rem;margin-top:8px}.wr-risk-card--hero .wr-kpi-note{color:#c7d5df}.wr-dead-count{align-items:center;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.12);border-radius:8px;bottom:20px;display:flex;gap:10px;left:22px;padding:9px 12px;position:absolute}.wr-dead-count strong{font-size:1.2rem}.wr-risk-card--alert{background:var(--wr-danger-soft);border-color:#f1c7c2}.wr-risk-card--alert .wr-kpi-label,.wr-risk-card--alert .wr-kpi-value{color:var(--wr-danger)}.wr-risk-card--warning{background:var(--wr-amber-soft);border-color:#eed6ab}.wr-risk-card--warning .wr-kpi-label,.wr-risk-card--warning .wr-kpi-value{color:var(--wr-amber)}
    .wr-stock-strip{background:var(--wr-surface);border:1px solid var(--wr-line);border-radius:var(--wr-radius);display:grid;grid-template-columns:repeat(4,1fr);margin-bottom:16px}.wr-stock-metric{padding:13px 16px}.wr-stock-metric+.wr-stock-metric{border-left:1px solid var(--wr-line)}.wr-stock-metric .wr-kpi-value{font-size:1.25rem;margin-top:5px}
    .wr-panel{background:var(--wr-surface);border:1px solid var(--wr-line);border-radius:var(--wr-radius);box-shadow:0 5px 18px rgba(27,48,68,.055);overflow:hidden}.wr-panel-head{align-items:center;border-bottom:1px solid var(--wr-line);display:flex;justify-content:space-between;padding:14px 16px}.wr-panel-head h4{font-size:.98rem;font-weight:750;margin:0}
    .wr-table{margin:0}.wr-table thead th{background:#f7f9fb;border-bottom-color:var(--wr-line);color:#526276;font-size:.74rem;font-weight:750;letter-spacing:.025em;padding:10px 12px;text-transform:uppercase;white-space:nowrap}.wr-table tbody td{border-color:#edf1f4;padding:11px 12px;vertical-align:middle}.wr-table tbody tr{transition:background-color 160ms ease}.wr-table tbody tr:hover{background:#f8fafb}.wr-table a{color:#245f82;font-weight:700;text-decoration:none}.wr-table a:hover{text-decoration:underline}.wr-number{font-variant-numeric:tabular-nums}.wr-status{border-radius:999px;display:inline-flex;font-size:.72rem;font-weight:750;line-height:1;padding:6px 9px}.wr-status--dead{background:var(--wr-danger-soft);color:var(--wr-danger)}.wr-status--incoming{background:var(--wr-success-soft);color:var(--wr-success)}.wr-status--unknown{background:var(--wr-amber-soft);color:var(--wr-amber)}
    .wr-shell>*{animation:wr-rise 420ms cubic-bezier(.22,.75,.25,1) both}.wr-shell>*:nth-child(2){animation-delay:45ms}.wr-shell>*:nth-child(3){animation-delay:90ms}.wr-shell>*:nth-child(4){animation-delay:135ms}@keyframes wr-rise{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}
    @media(max-width:991.98px){.wr-risk-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.wr-risk-card--hero{grid-column:1/-1;grid-row:auto;min-height:210px}.wr-stock-strip{grid-template-columns:repeat(2,1fr)}.wr-stock-metric:nth-child(3){border-left:0;border-top:1px solid var(--wr-line)}.wr-stock-metric:nth-child(4){border-top:1px solid var(--wr-line)}}
    @media(max-width:575.98px){.wr-page-head{align-items:stretch}.wr-actions,.wr-actions .btn,.wr-actions form{width:100%}.wr-actions .btn{justify-content:center}.wr-risk-grid{grid-template-columns:1fr}.wr-risk-card--hero{grid-column:auto}.wr-stock-strip{grid-template-columns:1fr}.wr-stock-metric+.wr-stock-metric{border-left:0;border-top:1px solid var(--wr-line)}}
    @media(prefers-reduced-motion:reduce){.wr-shell>*,.wr-table tbody tr,.wr-actions .btn,.wr-filter-actions .btn{animation:none!important;transition:none!important}}
</style>
